#!/usr/bin/env python3
"""K2 run 2 agent 2 source census. Read-only over the Lean tree.
Usage: k2_census.py <tree> <out.json>
Classifies every keyword occurrence as code / comment / string by a
lexer that tracks nested block comments /- -/ (incl. doc comments /-- /-!),
line comments --, and string literals "..." (with backslash escapes).
Then BFS import closure from root modules over `import X` lines of
project files only (Mathlib / Comparator imports are external, recorded but
not expanded). .lake/ is excluded via `git ls-files` filter."""
import re, sys, json, subprocess, hashlib, os, bisect
T = sys.argv[1]
files = subprocess.run(["git","-C",T,"ls-files"],capture_output=True,text=True).stdout.split("\n")
files = [f for f in files if f.endswith(".lean") and not f.startswith(".lake/")]
KW = ["sorry","axiom","admit","native_decide","implemented_by","extern","unsafe","opaque","set_option","macro","elab"]
kwre = re.compile(r"(?<![A-Za-z0-9_.'!?])(" + "|".join(KW) + r")(?![A-Za-z0-9_'!?])")
def classify(src):
    """return list of same length as src, each char tagged 'c' code,'m' comment,'s' string"""
    tags = ['c']*len(src); i=0; n=len(src); depth=0
    while i<n:
        if depth>0:
            if src.startswith("/-",i): depth+=1; tags[i]=tags[i+1]='m'; i+=2; continue
            if src.startswith("-/",i): depth-=1; tags[i]=tags[i+1]='m'; i+=2; continue
            tags[i]='m'; i+=1; continue
        if src.startswith("/-",i): depth=1; tags[i]=tags[i+1]='m'; i+=2; continue
        if src.startswith("--",i):
            j=src.find("\n",i); j=n if j<0 else j
            for k in range(i,j): tags[k]='m'
            i=j; continue
        if src[i]=='"':
            j=i+1
            while j<n and src[j]!='"':
                if src[j]=='\\': j+=1
                j+=1
            for k in range(i,min(j+1,n)): tags[k]='s'
            i=j+1; continue
        i+=1
    return tags
declre = re.compile(r"^\s*(?:@\[[^\]]*\]\s*)?(?:(?:private|protected|noncomputable|nonrec|partial|unsafe|scoped|local)\s+)*(theorem|lemma|def|abbrev|instance|structure|class|inductive|axiom|opaque|example|macro|elab|syntax|macro_rules|elab_rules)\b\s*([^\s:(\[{]*)")
hits=[]; counts={k:{"code":0,"comment":0,"string":0} for k in KW}
for f in files:
    src=open(os.path.join(T,f),encoding="utf-8").read()
    tags=classify(src)
    lines=src.split("\n"); offs=[0]
    for L in lines: offs.append(offs[-1]+len(L)+1)
    for m in kwre.finditer(src):
        kw=m.group(1); pos=m.start(); tag=tags[pos]
        kind={"c":"code","m":"comment","s":"string"}[tag]
        counts[kw][kind]+=1
        ln=bisect.bisect_right(offs,pos)
        decl=None
        for L in range(ln-1,-1,-1):
            if tags[offs[L]]=='m': continue
            dm=declre.match(lines[L])
            if dm: decl=f"{dm.group(1)} {dm.group(2)}".strip(); break
        hits.append({"file":f,"line":ln,"keyword":kw,"kind":kind,"enclosing_decl":decl,"text":lines[ln-1].strip()})
top={}
for f in files: top[f.split("/")[0]]=top.get(f.split("/")[0],0)+1
def file_of(m): return m.replace(".","/")+".lean"
imp=re.compile(r"^\s*import\s+(\S+)",re.M)
fileset=set(files)
def closure(root):
    seen=set(); ext=set(); stack=[root]
    while stack:
        m=stack.pop()
        if m in seen: continue
        fn=file_of(m)
        if fn not in fileset: ext.add(m); continue
        seen.add(m)
        src=open(os.path.join(T,fn),encoding="utf-8").read()
        for mm in imp.findall(src): stack.append(mm)
    return seen, ext
out={"files":len(files),"by_top_dir":top,"keyword_counts":counts,"hits":hits}
for root in ["NavierStokes.ComparatorSolution","Euler.Solution","NavierStokes","Euler"]:
    seen,ext=closure(root)
    out["closure_"+root]={"size_project_modules":len(seen),"external_imports":sorted(ext),
        "ComparatorChallenges_members":sorted(m for m in seen if m.startswith("ComparatorChallenges")),
        "members":sorted(seen)}
out["importers_of_ComparatorChallenges"]=[f for f in files if re.search(r"^\s*import\s+ComparatorChallenges",open(os.path.join(T,f),encoding="utf-8").read(),re.M)]
sha={}
for f in ["NavierStokes/ComparatorSolution.lean","Euler/Solution.lean","ComparatorChallenges/NavierStokes.lean","ComparatorChallenges/Euler.lean"]:
    sha[f]=hashlib.sha256(open(os.path.join(T,f),"rb").read()).hexdigest()
out["sha256"]=sha
json.dump(out,open(sys.argv[2],"w"),indent=1)
print(json.dumps({k:v for k,v in out.items() if k!="hits" and not k.startswith("closure_")},indent=1))
for k,v in out.items():
    if k.startswith("closure_"): print(k,v["size_project_modules"],v["external_imports"],v["ComparatorChallenges_members"])
print("code hits:")
for h in hits:
    if h["kind"]=="code": print(h)
print("string hits:")
for h in hits:
    if h["kind"]=="string": print(h)

