#!/usr/bin/env python3
"""Raw word-boundary cross-check (no comment/string lexing) of the keyword census,
independent of k2_census.py's lexer, plus a scan for `#print` / `sorryAx` lines
and a count of .lean files on disk outside .lake/ (to compare with git ls-files).
Usage: k2_rawcheck.py <tree>"""
import os, re, sys
T = sys.argv[1]
KW = ["sorry","axiom","admit","native_decide","implemented_by","extern","unsafe","opaque","set_option","macro","elab"]
files = []
for root, dirs, fns in os.walk(T):
    if os.path.basename(root) == ".lake" and os.path.dirname(root) == T:
        dirs[:] = []; continue
    dirs[:] = [d for d in dirs if not (root == T and d == ".lake")]
    for fn in fns:
        if fn.endswith(".lean"): files.append(os.path.join(root, fn))
print("lean files on disk outside .lake/:", len(files))
raw = {k: 0 for k in KW}
ctx = []
for f in files:
    for i, line in enumerate(open(f, encoding="utf-8"), 1):
        for k in KW:
            if re.search(r"\b" + k + r"\b", line):
                raw[k] += 1
                if k != "sorry": ctx.append((os.path.relpath(f, T), i, k, line.rstrip()))
        if "#print" in line or "sorryAx" in line:
            ctx.append((os.path.relpath(f, T), i, "#print/sorryAx", line.rstrip()))
print("raw word-boundary counts (code+comment+string):", raw)
for c in ctx: print(c)
